// --- Audio Helper Functions ---

function createBlob(data: Float32Array): Blob {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) {
        int16[i] = data[i] * 32768;
    }
    const bytes = new Uint8Array(int16.buffer);
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
        binary += String.fromCharCode(bytes[i]);
    }
    return {
        data: btoa(binary),
        mimeType: 'audio/pcm;rate=16000',
    };
}

function decode(base64: string) {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
}

async function decodeAudioData(
    data: Uint8Array,
    ctx: AudioContext,
    sampleRate: number,
    numChannels: number,
): Promise<AudioBuffer> {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

    for (let channel = 0; channel < numChannels; channel++) {
        const channelData = buffer.getChannelData(channel);
        for (let i = 0; i < frameCount; i++) {
            channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
        }
    }
    return buffer;
}


const ChatAssistant: React.FC<ChatAssistantProps> = ({ isOpen, onClose, initialPrompt }) => {
  const [mode, setMode] = useState<'text' | 'live'>('text');

  // Text Chat States
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messageListRef = useRef<HTMLDivElement>(null);

  // Live Chat States
  const [liveStatus, setLiveStatus] = useState<'idle' | 'connecting' | 'connected' | 'error'>('idle');
  const [isSpeaking, setIsSpeaking] = useState(false);

  // Refs for Live API
  const audioContextRef = useRef<AudioContext | null>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);
  const inputSourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sessionRef = useRef<any>(null);

  useEffect(() => {
    if (isOpen) {
      setMessages([]);
      if (initialPrompt) {
        setMessages([{ text: initialPrompt, sender: 'assistant' }]);
      }
      setMode('text'); // Reset to text mode on open
    } else {
        stopLiveSession(); // Ensure cleanup on close
    }
  }, [isOpen, initialPrompt]);

  useEffect(() => {
    if (messageListRef.current) {
      messageListRef.current.scrollTop = messageListRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  // Cleanup on unmount
  useEffect(() => {
      return () => {
          stopLiveSession();
      };
  }, []);

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputValue.trim() || isLoading) return;

    const userMessage: Message = { text: inputValue, sender: 'user' };
    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setIsLoading(true);

    const responseText = await sendMessage(inputValue);

    const assistantMessage: Message = { text: responseText, sender: 'assistant' };
    setMessages(prev => [...prev, assistantMessage]);
    setIsLoading(false);
  };

  const startLiveSession = async () => {
      setLiveStatus('connecting');
      try {
          const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

          audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
          const stream = await navigator.mediaDevices.getUserMedia({ audio: { sampleRate: 16000, channelCount: 1 } });
          mediaStreamRef.current = stream;

          const sessionPromise = ai.live.connect({
              model: 'gemini-2.5-flash-native-audio-preview-09-2025',
              callbacks: {
                  onopen: () => {
                      setLiveStatus('connected');
                      console.log("Live session connected");

                      // Setup Input Stream
                      if (!audioContextRef.current) return;

                      // Use a separate context for input to ensure 16kHz capture if possible, 
                      // or just rely on the ScriptProcessor to downsample.
                      // For simplicity in this demo, we use a ScriptProcessor on a standard context.
                      // Note: ScriptProcessor is deprecated but widely supported for this use case in demos.
                      const inputContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
                      const source = inputContext.createMediaStreamSource(stream);
                      const scriptProcessor = inputContext.createScriptProcessor(4096, 1, 1);

                      scriptProcessor.onaudioprocess = (e) => {
                          const inputData = e.inputBuffer.getChannelData(0);
                          const pcmBlob = createBlob(inputData);
                          sessionPromise.then(session => {
                              session.sendRealtimeInput({ media: pcmBlob });
                          });
                      };

                      source.connect(scriptProcessor);
                      scriptProcessor.connect(inputContext.destination);

                      inputSourceRef.current = source;
                      processorRef.current = scriptProcessor;
                  },
                  onmessage: async (message: LiveServerMessage) => {
                       const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
                       if (base64Audio && audioContextRef.current) {
                           setIsSpeaking(true);
                           const ctx = audioContextRef.current;
                           nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);

                           const audioBuffer = await decodeAudioData(
                               decode(base64Audio),
                               ctx,
                               24000,
                               1
                           );

                           const source = ctx.createBufferSource();
                           source.buffer = audioBuffer;
                           source.connect(ctx.destination);
                           source.start(nextStartTimeRef.current);
                           source.onended = () => setIsSpeaking(false);

                           nextStartTimeRef.current += audioBuffer.duration;
                       }
                  },
                  onclose: () => {
                      setLiveStatus('idle');
                      console.log("Live session closed");
                  },
                  onerror: (err) => {
                      console.error("Live session error:", err);
                      setLiveStatus('error');
                  }
              },
              config: {
                  responseModalities: [Modality.AUDIO],
                  systemInstruction: "You are a helpful, professional, and friendly customer support agent for IntelliTrack, a global courier service. Your goal is to assist users with tracking shipments, explaining services, and resolving issues efficiently. Be concise in your spoken responses."
              }
          });

          sessionRef.current = sessionPromise;

      } catch (error) {
          console.error("Failed to start live session:", error);
          setLiveStatus('error');
      }
  };

  const stopLiveSession = () => {
      if (mediaStreamRef.current) {
          mediaStreamRef.current.getTracks().forEach(track => track.stop());
          mediaStreamRef.current = null;
      }
      if (processorRef.current) {
          processorRef.current.disconnect();
          processorRef.current = null;
      }
      if (inputSourceRef.current) {
          inputSourceRef.current.disconnect();
          inputSourceRef.current = null;
      }
      if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
          audioContextRef.current.close();
          audioContextRef.current = null;
      }

      // Close session if possible (wrapper doesn't expose clean close directly on promise, 
      // but usually we just stop sending and cut stream in this pattern).
      // Ideally, the SDK would have a disconnect method on the session object.
      // We will rely on stream cleanup to end effective communication.

      setLiveStatus('idle');
      setIsSpeaking(false);
  };

  const toggleMode = () => {
      if (mode === 'text') {
          setMode('live');
          startLiveSession();
      } else {
          stopLiveSession();
          setMode('text');
      }
  };

  if (!isOpen) {
    return null;
  }

  return (
    <div style={styles.overlay} onClick={onClose}>
      <style>{`
          @keyframes pulse-ring {
              0% { transform: translate(-50%, -50%) scale(0.8); opacity: 0.8; }
              100% { transform: translate(-50%, -50%) scale(2.5); opacity: 0; }
          }
      `}</style>
      <div style={styles.modal} onClick={(e) => e.stopPropagation()}>
        <div style={styles.header}>
            <h2 style={styles.title}>
                {mode === 'text' ? <Icon name="message-square" /> : <Icon name="headset" />}
                {mode === 'text' ? 'AI Assistant' : 'Live Support'}
            </h2>
            <button style={styles.modeToggle} onClick={toggleMode}>
                {mode === 'text' ? (
                    <>
                        <Icon name="headset" style={{width: 16, height: 16}} />
                        <span>Go Live</span>
                    </>
                ) : (
                    <>
                         <Icon name="message-square" style={{width: 16, height: 16}} />
                         <span>Text Chat</span>
                    </>
                )}
            </button>
            <button 
                className="chat-modal-close-button"
                onClick={onClose} 
                aria-label="Close assistant"
                style={{ position: 'static', transform: 'none' }}
            >
                <Icon name="close" />
            </button>
        </div>

        {mode === 'text' ? (
            <>
                <div ref={messageListRef} className="chat-message-list">
                {messages.map((msg, index) => (
                    <div key={index} className={`chat-bubble ${msg.sender}`}>
                    {msg.text}
                    </div>
                ))}
                {isLoading && (
                    <div className="chat-bubble assistant">
                    <div className="typing-indicator">
                        <span></span><span></span><span></span>
                    </div>
                    </div>
                )}
                </div>

                <form onSubmit={handleSendMessage} className="chat-input-form">
                <input
                    type="text"
                    value={inputValue}
                    onChange={(e) => setInputValue(e.target.value)}
                    className="chat-input"
                    placeholder="Ask a question..."
                    disabled={isLoading}
                />
                <button type="submit" className="chat-send-button" disabled={isLoading || !inputValue.trim()}>
                    <Icon name="package" />
                </button>
                </form>
            </>
        ) : (
            <div style={styles.liveContainer}>
                {liveStatus === 'connecting' && <p style={styles.statusText}>Connecting to Agent...</p>}

                {liveStatus === 'connected' && (
                    <>
                        <div style={styles.visualizerRing}>
                             {isSpeaking && <div style={styles.pulse}></div>}
                             <div style={{ position: 'relative', zIndex: 1 }}>
                                <Icon name="headset" style={{ width: 60, height: 60, color: isSpeaking ? 'white' : '#9ca3af' }} />
                             </div>
                        </div>
                        <p style={styles.statusText}>{isSpeaking ? "Agent Speaking..." : "Listening..."}</p>
                        <p style={styles.subStatusText}>Speak naturally to ask about your shipment.</p>
                    </>
                )}

                {liveStatus === 'error' && (
                    <div style={{color: '#ef4444', textAlign: 'center'}}>
                        <Icon name="alert-triangle" style={{width: 48, height: 48, margin: '0 auto 1rem'}} />
                        <p>Connection Failed. Please try again or switch to text chat.</p>
                        <button onClick={startLiveSession} style={{marginTop: '1rem', padding: '0.5rem 1rem', background: '#374151', border: 'none', color: 'white', borderRadius: '4px', cursor: 'pointer'}}>Retry</button>
                    </div>
                )}

                <div style={styles.liveControls}>
                     <button 
                        onClick={stopLiveSession}
                        style={{
                            background: '#ef4444',
                            border: 'none',
                            borderRadius: '50%',
                            width: '56px',
                            height: '56px',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            cursor: 'pointer',
                            color: 'white',
                            boxShadow: '0 4px 12px rgba(239, 68, 68, 0.4)'
                        }}
                     >
                         <Icon name="stop-circle" style={{width: 28, height: 28}} />
                     </button>
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default ChatAssistant;

import { useState, useEffect, useRef } from 'react';

// TypeScript definitions for the SpeechRecognition API
interface SpeechRecognition extends EventTarget {
  continuous: boolean;
  interimResults: boolean;
  lang: string;
  start(): void;
  stop(): void;
  onresult: ((this: SpeechRecognition, ev: SpeechRecognitionEvent) => any) | null;
  onerror: ((this: SpeechRecognition, ev: SpeechRecognitionErrorEvent) => any) | null;
  onend: ((this: SpeechRecognition, ev: Event) => any) | null;
}

interface SpeechRecognitionEvent extends Event {
  results: SpeechRecognitionResultList;
}

interface SpeechRecognitionErrorEvent extends Event {
  error: string;
}

declare global {
  interface Window {
    SpeechRecognition: { new (): SpeechRecognition };
    webkitSpeechRecognition: { new (): SpeechRecognition };
  }
}

export interface SpeechRecognitionHook {
  isListening: boolean;
  transcript: string;
  error: string | null;
  isSupported: boolean;
  startListening: () => void;
  stopListening: () => void;
}

const useSpeechRecognition = (language: string = 'en-US'): SpeechRecognitionHook => {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [error, setError] = useState<string | null>(null);
  const recognitionRef = useRef<SpeechRecognition | null>(null);

  useEffect(() => {
    const SpeechRecognitionAPI = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (SpeechRecognitionAPI) {
      recognitionRef.current = new SpeechRecognitionAPI();
      const recognition = recognitionRef.current;
      recognition.continuous = false;
      recognition.interimResults = false;
      recognition.lang = language;

      recognition.onresult = (event: SpeechRecognitionEvent) => {
        const currentTranscript = event.results[0][0].transcript;
        setTranscript(currentTranscript);
      };

      recognition.onerror = (event: SpeechRecognitionErrorEvent) => {
        if (event.error === 'not-allowed') {
          setError("Microphone permission was denied. Please enable it in your browser settings to use voice commands.");
        } else {
          setError(`Speech recognition error: ${event.error}`);
        }
        setIsListening(false);
      };

      recognition.onend = () => {
        setIsListening(false);
      };
    } else {
      setError('Speech recognition is not supported in this browser.');
    }

    return () => {
      if (recognitionRef.current) {
        recognitionRef.current.stop();
      }
    };
  }, [language]);

  const startListening = () => {
    if (recognitionRef.current && !isListening) {
      setTranscript('');
      setError(null);
      recognitionRef.current.start();
      setIsListening(true);
    }
  };

  const stopListening = () => {
    if (recognitionRef.current && isListening) {
      recognitionRef.current.stop();
      setIsListening(false);
    }
  };

  return {
    isListening,
    transcript,
    error,
    isSupported: !!(window.SpeechRecognition || window.webkitSpeechRecognition),
    startListening,
    stopListening,
  };
};

export default useSpeechRecognition;

import React, { useState, useRef, useEffect } from 'react';

interface EmailVerificationProps {
  onVerify: () => void;
  userEmail: string;
}

const OTP_LENGTH = 6;
const RESEND_COOLDOWN = 30; // seconds

const EmailVerification: React.FC<EmailVerificationProps> = ({ onVerify, userEmail }) => {
  const [otp, setOtp] = useState<string[]>(new Array(OTP_LENGTH).fill(''));
  const [resendTimer, setResendTimer] = useState(0);
  const inputRefs = useRef<(HTMLInputElement | null)[]>([]);

  useEffect(() => {
    // Fix: `setTimeout` returns a number in browsers, not a NodeJS.Timeout.
    let timer: ReturnType<typeof setTimeout>;
    if (resendTimer > 0) {
      timer = setTimeout(() => setResendTimer(resendTimer - 1), 1000);
    }
    return () => clearTimeout(timer);
  }, [resendTimer]);

  useEffect(() => {
    // Focus the first input on mount
    inputRefs.current[0]?.focus();
  }, []);

  const handleChange = (element: HTMLInputElement, index: number) => {
    if (isNaN(Number(element.value))) return; // Only allow numbers

    const newOtp = [...otp];
    newOtp[index] = element.value;
    setOtp(newOtp);

    // Focus next input
    if (element.value !== '' && index < OTP_LENGTH - 1) {
      inputRefs.current[index + 1]?.focus();
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>, index: number) => {
    // Move focus back on backspace
    if (e.key === 'Backspace' && otp[index] === '' && index > 0) {
      inputRefs.current[index - 1]?.focus();
    }
  };

  const handlePaste = (e: React.ClipboardEvent<HTMLInputElement>) => {
    const pastedData = e.clipboardData.getData('text').slice(0, OTP_LENGTH);
    if (!/^\d+$/.test(pastedData)) return; // Only paste if it's all digits

    const newOtp = [...otp];
    for (let i = 0; i < pastedData.length; i++) {
        if (i < OTP_LENGTH) {
            newOtp[i] = pastedData[i];
        }
    }
    setOtp(newOtp);
    inputRefs.current[pastedData.length - 1]?.focus();
  };

  const handleResendCode = () => {
    console.log("Resending verification code...");
    setResendTimer(RESEND_COOLDOWN);
    setOtp(new Array(OTP_LENGTH).fill(''));
    inputRefs.current[0]?.focus();
    // In a real app, you would trigger the API to resend the code here
  };

  const isFormComplete = otp.every(digit => digit !== '');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (isFormComplete) {
      console.log("Verifying OTP:", otp.join(''));
      onVerify(); // In this mock, any complete code is accepted
    }
  };

  return (
    <div className="email-verification-container">
      <video
        id="verification-video-bg"
        src="https://videos.pexels.com/video-files/5495856/5495856-hd_1920_1080_25fps.mp4"
        autoPlay
        loop
        muted
        playsInline
      ></video>
      <div className="verification-content">
        <h1 className="verification-title">Verify Your Shipment</h1>
        <p className="verification-subtitle">
          For your security, a 6-digit verification code has been sent to <strong>{userEmail}</strong>. Please enter it below.
        </p>
        <form onSubmit={handleSubmit}>
          <div className="otp-inputs" onPaste={handlePaste}>
            {otp.map((data, index) => (
              <input
                key={index}
                ref={el => { inputRefs.current[index] = el; }}
                className="otp-input"
                type="text"
                name="otp"
                maxLength={1}
                value={data}
                onChange={e => handleChange(e.target, index)}
                onKeyDown={e => handleKeyDown(e, index)}
                onFocus={e => e.target.select()}
              />
            ))}
          </div>
          <button
            className="verification-button"
            type="submit"
            disabled={!isFormComplete}
          >
            Verify & Track
          </button>
        </form>
        <p className="resend-code-text">
          Didn't receive the code?{' '}
          <button
            className="resend-code-button"
            onClick={handleResendCode}
            disabled={resendTimer > 0}
          >
            {resendTimer > 0 ? `Resend in ${resendTimer}s` : 'Resend Code'}
          </button>
        </p>
      </div>
    </div>
  );
};

export default EmailVerification;
